package main

import "fmt"

func countSetBits(n int) int {
	count := 0
	for n > 0 {
		count += n & 1
		n >>= 1
	}
	return count
}

func main() {
	var n int
	fmt.Scan(&n)
	fmt.Println(countSetBits(n))
}

